insert into chapters (chapter_id, title, description, sort_order, updated_at) values ('chapter-6', '第六章：空间数据的采集与处理', '数据源、数字化、编辑、变换与质量控制', 6, datetime('now')) on conflict(chapter_id) do update set title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, updated_at = excluded.updated_at;
